correction.text:
{
  "corrected": "I am Karthik and I have two years of experience in sales.",
  "mistakes": [
    {
      "wrong": "Myself Karthik",
      "right": "I am Karthik",
      "type": "grammar",
      "explanation_tamil": "கார்த்திக் என உட்படும் 'மய்யஸ்' என்பது தவறு; 'நான்' என்பதால் 'என்' பயன்படுத்த வேண்டும்."
    },
    {
      "wrong": "and I am having",
      "right": "and I have",
      "type": "style",
      "explanation_tamil": "இருப்போகும் என்பது தவறு; இது 'நான்' என்பதால் 'என்' பயன்படுத்த வேண்டும்."
    }
  ]
}

{
  "corrected": "I have been working in this company since 2019.",
  "mistakes": [
    {
      "wrong": "I am working in this company since 2019.",
      "right": "I have been working in this company since 2019.",
      "type": "grammar",
      "explanation_tamil": "The verb 'am working' is incorrect for this context; you should use 'have been working' to show continuous experience."
    }
  ]
}

{
  "corrected": "Please revert back to me today.",
  "mistakes": [
    {
      "wrong": "Please revert back to me today itself.",
      "right": "Please revert back to me today.","type":"grammar","explanation_tamil": "The word 'itself' is unnecessary and makes the sentence sound unnatural in this context."
    }
  ]
}

{
  "corrected": "We discussed the budget, and he said it was fine.",
  "mistakes": [
    {
      "wrong": "discussed about",
      "right": "discussed",
      "type": "grammar",
      "explanation_tamil": "You do not need to add 'about' after 'discussed' in this context."
    },
    {
      "wrong": "he told that it is fine",
      "right": "he said it was fine",
      "type": "style",
      "explanation_tamil": "'Told' is too informal for business; 'said' is more professional."
    }
  ]
}

{
  "corrected": "Kindly do the needful and send the files.",
  "mistakes": []
}

