  "corrected": "What is your **full** name?",
  "mistakes": [
    {
      "wrong": "good name",
      "right": "full name",
      "type": "grammar",
      "explanation_tamil": "Good name is not a grammatical term; you should use 'full name' to refer to the complete name."
    }
  ]
}

